<?php

declare(strict_types=1);

use Illuminate\Foundation\Testing\RefreshDatabase;
use Vaulter\Data\Sharing\ShareLinkInput;
use Vaulter\Data\Sharing\ShareLinkUpdate;
use Vaulter\Enums\Events\EventType;
use Vaulter\Models\Webhooks\Outbox;
use Vaulter\Operations\AccessOperations;
use Vaulter\Operations\OperationContext;
use Vaulter\Operations\ShareOperations;
use Vaulter\Tests\Access\AccessTestHelpers;
use Vaulter\Tests\TestCase;

uses(TestCase::class, RefreshDatabase::class);

it('keeps access.inheritance_changed sequence null because the node sequence does not move', function (): void {
    config()->set('vaulter.access.permission_driver', 'database');
    $drive = AccessTestHelpers::storage();
    $access = app()->makeWith(AccessOperations::class, ['context' => OperationContext::system($drive, 'p52 review')]);
    $parent = AccessTestHelpers::folder($drive, null, 'parent');
    $child = AccessTestHelpers::folder($drive, $parent, 'child');
    $before = $child->sequence;

    $access->restrictInheritance($child->id);

    $after = $child->fresh()->sequence;
    $payload = Outbox::query()->where('event', EventType::InheritanceChanged->value)->sole()->payload;

    expect([
        'node_sequence_before' => $before,
        'node_sequence_after' => $after,
        'envelope_sequence' => $payload['sequence'],
        'data' => $payload['data'],
    ])->toBe([
        'node_sequence_before' => $before,
        'node_sequence_after' => $before,
        'envelope_sequence' => null,
        'data' => ['inherits' => false],
    ]);
});

it('does not emit share.updated when max_uses is set to the value already stored', function (): void {
    config()->set('vaulter.features.share_links', true);
    config()->set('vaulter.access.permission_driver', 'database');
    $drive = AccessTestHelpers::storage();
    $node = AccessTestHelpers::folder($drive, null, 'shared');
    $shares = app()->makeWith(ShareOperations::class, ['context' => OperationContext::system($drive, 'p52 review')]);
    $minted = $shares->create($node->id, new ShareLinkInput);
    $shares->update($node->id, $minted->link->id, new ShareLinkUpdate(maxUses: 3));
    Outbox::query()->where('event', EventType::ShareUpdated->value)->delete();

    $shares->update($node->id, $minted->link->id, new ShareLinkUpdate(maxUses: 3));

    $rows = Outbox::query()->where('event', EventType::ShareUpdated->value)->get();
    $stored = AccessTestHelpers::shareRow($minted)->max_uses;

    expect([
        'stored_max_uses' => $stored,
        'events' => $rows->count(),
        'changed' => $rows->first()->payload['data']['changed'] ?? null,
    ])->toBe([
        'stored_max_uses' => 3,
        'events' => 0,
        'changed' => null,
    ]);
});
EOF
